import inspect

import six
import logging

logger = logging.getLogger('agent_ute')


class Version(object):
    def __init__(self, cls, deprecated=True, default=False):
        self._validate_cls(cls)
        self.cls = cls
        self.deprecated = deprecated
        self.default = default

    @classmethod
    def _validate_cls(cls, obj):
        if isinstance(obj, six.string_types):
            raise VersionException("Obj cannot be string")
        elif not (inspect.isfunction(obj) or inspect.ismethod(obj)) and not inspect.isclass(obj):
            raise VersionException("Obj cannot be instance of class")


class _Versions(object):
    def __init__(self, versions):
        self._validate_versions(versions)
        self._versions = self._map_versions(versions)
        self._default_version = self._get_default_version()

    @classmethod
    def _validate_versions(cls, versions):
        if len(versions) < 2:
            raise VersionsException("Versions should have at least two versions: 1 deprecated and new implementation")
        if not all([isinstance(version, Version) for version in versions]):
            raise VersionsException("One or more Objects in list is not instance of Version")
        if [version.deprecated for version in versions if version.deprecated].count(True) != 1:
            raise VersionsException("Versions should have exactly 1 deprecated version")
        if [version.default for version in versions if version.default].count(True) != 1:
            raise VersionsException("Versions should have exactly 1 default version")

    @classmethod
    def _map_versions(cls, versions):
        return {version.cls.__name__: version for version in versions}

    def _get_default_version(self):
        for version in self._versions.values():
            if version.default:
                return version

    def __getitem__(self, item):
        if item:
            try:
                version = self._versions[item]
            except KeyError:
                raise VersionsException("Version {version} is not found in list {versions}". format(version=item,
                                                                                                    versions=str(list(self._versions.values()))))
        else:
            version = self._default_version

        return version.cls, version.deprecated


class VersionSelector(object):
    def __new__(cls, *args, **kwargs):
        version = kwargs.get('version')

        if version:
            version = cls._parse_version(version)
        all_versions = _Versions(cls.all_versions())
        return cls._find_version(all_versions, version)

    @classmethod
    def _parse_version(cls, version):
        return version if isinstance(version, six.string_types) else version.__name__

    @classmethod
    def _find_version(cls, all_versions, version):
        found_version, is_deprecated = all_versions[version]
        # if is_deprecated:
        #     logger.warning(
        #         "Object {object_name} is deprecated".format(object_name=found_version.__name__))
        return found_version

    @classmethod
    def all_versions(cls):
        """It should returns list of versions"""
        raise NotImplementedError


class VersionException(Exception):
    """Exception raised by Version class"""


class VersionsException(Exception):
    """Exception raised by _Versions class"""
